#include "MultiscatteringReference.h"
#include <iostream>
#include <iomanip>
int main(){const double a2=std::pow(double(.045f),4),cap=1/(1+a2),pi=std::acos(-1.);double old=0,stable=0,reference=0;for(auto node:IBLReferenceNodes(256)){double u=node.x*cap,hz=sqrt((1-u)/(1+(a2-1)*u)),hx=sqrt(1-hz*hz),den=1-hz*hz+a2*hz*hz,pdf=a2/(4*pi*den*den);auto l=glm::normalize(glm::vec3(2*hx*hz,0,2*hz*hz-1));auto h=glm::normalize(glm::vec3(0,0,1)+l);float aa=std::pow(.045f,4),nh=h.z;float before=std::max(1-nh*nh,0.f)+aa*nh*nh;auto cross=glm::cross(glm::vec3(0,0,1),h);float after=glm::dot(cross,cross)+aa*nh*nh;float vis=.5f/(l.z+l.z*sqrt(l.z*l.z*(1-aa)+aa)/l.z);old+=aa/(float(pi)*before*before)*vis*l.z*cap*node.y/pdf;stable+=aa/(float(pi)*after*after)*vis*l.z*cap*node.y/pdf;double nl=2*hz*hz-1;reference+=2*nl/(nl+sqrt(nl*nl+a2*(1-nl*nl)))*cap*node.y;}std::cout<<std::setprecision(15)<<"CPU FP32 old denominator "<<old<<"\nCPU FP32 cross denominator "<<stable<<"\nFP64 SS energy "<<reference<<"\n";}
